// Full text of the three editions of the Adjudix Code of ADR Procedure, for
// the on-site reader. The JSON files are generated by
// web/scripts/adjudix-code/build.py alongside the PDFs — never edit by hand.
import code2018 from "./code-2018.json";
import code2021 from "./code-2021.json";
import code2026 from "./code-2026.json";

export interface CodeSection {
  no: string;
  title: string;
  body: string[] | null;
  definitions?: { term: string; text: string }[];
  /** The edition in which this section first appeared. */
  since: number;
}

export interface CodeChapter {
  no: string;
  title: string;
  since: number;
  sections: CodeSection[];
}

export interface CodePart {
  no: string;
  title: string;
  chapters: CodeChapter[];
}

export interface CodeText {
  year: number;
  title: string;
  note: string;
  intro: string[];
  principles: { title: string; body: string }[];
  close: string;
  parts: CodePart[];
  closingNote: string;
}

const TEXTS: Record<string, CodeText> = {
  "2018": code2018 as CodeText,
  "2021": code2021 as CodeText,
  "2026": code2026 as CodeText,
};

export function getCodeText(year: string): CodeText | undefined {
  return TEXTS[year];
}

export const sectionId = (no: string) => `section-${no.toLowerCase()}`;
export const chapterId = (no: string) => `chapter-${no.toLowerCase()}`;
export const partId = (no: string) => `part-${no.toLowerCase()}`;
